"""A history retains the newest capacity samples in insertion order.

The display uses power-of-two time buckets. Client code may persist a zoom
level, so level zero must remain a one-second bucket across releases.
"""

from collections import deque
from math import floor, log2


class History:
    def __init__(self, capacity):
        if capacity < 1:
            raise ValueError("capacity must be positive")
        self._samples = deque(maxlen=capacity)

    def append(self, sample):
        self._samples.append(sample)

    def samples(self):
        return tuple(self._samples)


def zoom_level(seconds):
    """Map positive seconds to its containing power-of-two bucket.

    A bucket has width 2**level. Taking log base two on both sides
    gives level = log2(width). Rounding down selects the bucket that
    contains seconds, so 2**level <= seconds < 2**(level + 1).
    """
    if seconds <= 0:
        raise ValueError("seconds must be positive")
    # Level zero must remain a one-second bucket for persisted client settings.
    return floor(log2(seconds))
